cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>
#include <algorithm>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ int floor_div_int(int a, int b) {
  // b > 0
  int q = a / b;
  int r = a - q * b;
  if (r != 0 && r < 0) --q;
  return q;
}

__device__ __forceinline__ int ceil_div_int(int a, int b) {
  // b > 0
  return -floor_div_int(-a, b);
}

// Cooperative tiled ConvTranspose2d (gather formulation).
//
// Each thread block cooperatively computes a (TH x TW) tile of output spatial
// positions for CO_TILE output channels of one batch element:
//   - the group's filter slice is staged into shared memory,
//   - the input patch that can contribute to this output tile is staged
//     into shared memory,
//   - each thread then accumulates over (ci, kh, kw) from shared memory.
//
// y[n, co, oh, ow] = bias[co]
//   + sum_{ci in group(co)} sum_{kh,kw} x[n, ci, hi, wi] * w[ci, co_l, kh, kw]
// where oh = hi*sh - ph + kh*dh  =>  hi = (oh + ph - kh*dh) / sh (if integral)
//       ow = wi*sw - pw + kw*dw  =>  wi = (ow + pw - kw*dw) / sw (if integral)
template <int CO_TILE>
__global__ void conv_transpose2d_cute_kernel(
    const float* __restrict__ Xp,
    const float* __restrict__ Wp,
    const float* __restrict__ Bp,
    float* __restrict__ Yp,
    int N, int IC, int H, int W,
    int OC, int HO, int WO,
    int KH, int KW,
    int ICG, int OCG,
    int sh, int sw, int ph, int pw, int dh, int dw,
    int PHmax, int PWmax)
{
  constexpr int TH = 8;
  constexpr int TW = 16;
  constexpr int OW_PER_THREAD = 4;   // wider CTA output tile: 4*TW columns per block
  const int tid  = threadIdx.x;
  const int t_ow = tid % TW;
  const int t_oh = tid / TW;
  const int ow0     = blockIdx.x * (OW_PER_THREAD * TW);   // each thread handles ow0+t_ow+j*TW
  const int oh0     = blockIdx.y * TH;
  const int n       = blockIdx.z % N;
  const int co_tile = blockIdx.z / N;
  const int co0     = co_tile * CO_TILE;
  const int g       = co0 / OCG;          // CO_TILE divides OCG, so tile is in one group
  const int ci0     = g * ICG;
  const int co_l0   = co0 - g * OCG;    // group-local base of this channel tile
  // Global memory tensors (CuTe)
  Tensor mX = make_tensor(make_gmem_ptr(Xp),
                          make_shape(N, IC, H, W),
                          make_stride((int64_t)IC * H * W, (int64_t)H * W, (int64_t)W, Int<1>{}));
  Tensor mW = make_tensor(make_gmem_ptr(Wp),
                          make_shape(IC, OCG, KH, KW),
                          make_stride((int64_t)OCG * KH * KW, (int64_t)KH * KW, (int64_t)KW, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Yp),
                          make_shape(N, OC, HO, WO),
                          make_stride((int64_t)OC * HO * WO, (int64_t)HO * WO, (int64_t)WO, Int<1>{}));
  // Shared memory tensors (CuTe)
  extern __shared__ float smem[];
  float* sW_ptr = smem;
  float* sX_ptr = smem + (size_t)CO_TILE * ICG * KH * KW;
  // Optimization: store the staged filter with the output-channel tile as the
  // innermost (stride-1) mode so the hot accumulation loop can fetch the
  // CO_TILE tap weights with vectorized float4/float2 shared-memory loads
  // instead of CO_TILE separate scalar loads (staging stays coalesced).
  Tensor sW = make_tensor(make_smem_ptr(sW_ptr),
                          make_shape(ICG, KH, KW, Int<CO_TILE>{}),
                          make_stride((int64_t)KH * KW * CO_TILE, (int64_t)KW * CO_TILE,
                                      (int64_t)CO_TILE, Int<1>{}));
  Tensor sX = make_tensor(make_smem_ptr(sX_ptr),
                          make_shape(ICG, PHmax, PWmax),
                          make_stride((int64_t)PHmax * PWmax, (int64_t)PWmax, Int<1>{}));
  // Per-row (kh -> ih) and per-column (kw -> iw) tap validity tables.
  int* sHtab = reinterpret_cast<int*>(sX_ptr + (size_t)ICG * PHmax * PWmax);
  int* sWtab = sHtab + TH * KH;
  float* sB_ptr = reinterpret_cast<float*>(sWtab + (size_t)(OW_PER_THREAD * TW) * KW);
  // Bounds of the input patch that can contribute to this wider output tile
  int hi_lo = max(0, ceil_div_int(oh0 + ph - (KH - 1) * dh, sh));
  int hi_hi = min(H - 1, floor_div_int(oh0 + TH - 1 + ph, sh));
  int wi_lo = max(0, ceil_div_int(ow0 + pw - (KW - 1) * dw, sw));
  int wi_hi = min(W - 1, floor_div_int(ow0 + OW_PER_THREAD * TW - 1 + pw, sw));
  int PH = hi_hi - hi_lo + 1; if (PH < 0) PH = 0;
  int PW = wi_hi - wi_lo + 1; if (PW < 0) PW = 0;
  // Stage the group's filter slice cooperatively
  {
    const int total = CO_TILE * ICG * KH * KW;
    for (int idx = tid; idx < total; idx += blockDim.x) {
      int kw = idx % KW;
      int t  = idx / KW;
      int kh = t % KH;
      t /= KH;
      int ci = t % ICG;
      int co = t / ICG;
      sW(ci, kh, kw, co) = mW(ci0 + ci, co_l0 + co, kh, kw);
    }
  }
  // Stage the contributing input patch cooperatively
  if (PH > 0 && PW > 0) {
    const int total = ICG * PH * PW;
    for (int idx = tid; idx < total; idx += blockDim.x) {
      int iw = idx % PW;
      int t  = idx / PW;
      int ih = t % PH;
      int ci = t / PH;
      sX(ci, ih, iw) = mX(n, ci0 + ci, hi_lo + ih, wi_lo + iw);
    }
  }
  // Precompute valid-tap tables in shared memory (cooperatively, once per
  // block) so the hot accumulation loop needs no integer div/mod or bounds
  // arithmetic per tap:
  //   sHtab[r*KH + kh] = hi - hi_lo (>= 0) iff tap (oh0+r, kh) contributes
  //   sWtab[c*KW + kw] = wi - wi_lo (>= 0) iff tap (ow0+c, kw) contributes
  {
    const int htotal = TH * KH;
    for (int idx = tid; idx < htotal; idx += blockDim.x) {
      int r    = idx / KH;
      int kh   = idx - r * KH;
      int oh_r = oh0 + r;
      int v = -1;
      if (oh_r < HO) {
        int num = oh_r + ph - kh * dh;
        if (num >= 0 && num % sh == 0) {
          int hi = num / sh;
          if (hi < H) v = hi - hi_lo;
        }
      }
      sHtab[idx] = v;
    }
    const int wtotal = (OW_PER_THREAD * TW) * KW;
    for (int idx = tid; idx < wtotal; idx += blockDim.x) {
      int c    = idx / KW;
      int kw   = idx - c * KW;
      int ow_c = ow0 + c;
      int v = -1;
      if (ow_c < WO) {
        int num = ow_c + pw - kw * dw;
        if (num >= 0 && num % sw == 0) {
          int wi = num / sw;
          if (wi < W) v = wi - wi_lo;
        }
      }
      sWtab[idx] = v;
    }
  }
  // Stage the output-channel bias tile once per block so the accumulator
  // initialization reuses shared memory instead of issuing CO_TILE global
  // loads per thread for the same few bias values.
  if (Bp != nullptr) {
    for (int idx = tid; idx < CO_TILE; idx += blockDim.x) {
      sB_ptr[idx] = Bp[co0 + idx];
    }
  }
  __syncthreads();
  // Wider output tiling: each thread computes FOUR horizontally spaced output
  // positions (ow[j] = ow0 + t_ow + j*TW) for all CO_TILE channels, so every
  // staged filter tap fetched from shared memory feeds 4*CO_TILE FMAs instead
  // of 2*CO_TILE, doubling shared-memory weight reuse per staged tap while
  // keeping per-j global stores coalesced across the warp.
  const int oh = oh0 + t_oh;
  int ow[OW_PER_THREAD];
  bool live[OW_PER_THREAD];
  bool any_live = false;
  #pragma unroll
  for (int j = 0; j < OW_PER_THREAD; ++j) {
    ow[j]   = ow0 + t_ow + j * TW;
    live[j] = (oh < HO) && (ow[j] < WO);
    any_live |= live[j];
  }
  if (!any_live) return;
  float acc[OW_PER_THREAD][CO_TILE];
  #pragma unroll
  for (int j = 0; j < OW_PER_THREAD; ++j) {
  #pragma unroll
  for (int j = 0; j < OW_PER_THREAD; ++j) {
    #pragma unroll
    for (int co = 0; co < CO_TILE; ++co) {
      acc[j][co] = (Bp != nullptr) ? sB_ptr[co] : 0.0f;
    }
  }
  if (PH > 0 && PW > 0) {
    // Table-driven accumulation: all per-tap integer div/mod/bounds checks
    // were hoisted into sHtab/sWtab, so the hot loop is a straight stream
    // of shared-memory gathers feeding the vectorized FMA block.
    const int* hrow = sHtab + t_oh * KH;
    const int* wcol = sWtab + t_ow * KW;
    for (int ci = 0; ci < ICG; ++ci) {
      const float* sXc = &sX(ci, 0, 0);
      for (int kh = 0; kh < KH; ++kh) {
        const int ih = hrow[kh];
        if (ih < 0) continue;
        const float* xrow = sXc + (size_t)ih * PWmax;
        const float* wkh  = &sW(ci, kh, 0, 0);
        for (int kw = 0; kw < KW; ++kw) {
          float xv[OW_PER_THREAD];
          bool any_ok = false;
          #pragma unroll
          for (int j = 0; j < OW_PER_THREAD; ++j) {
            const int iw = wcol[j * TW * KW + kw];
            const bool ok = live[j] && (iw >= 0);
            xv[j] = ok ? xrow[iw] : 0.0f;
            any_ok |= ok;
          }
          if (!any_ok) continue;
          const float* wbase = wkh + (size_t)kw * CO_TILE;
          if constexpr (CO_TILE % 4 == 0) {
            #pragma unroll
            for (int c4 = 0; c4 < CO_TILE / 4; ++c4) {
              float4 wv = reinterpret_cast<const float4*>(wbase)[c4];
              #pragma unroll
              for (int j = 0; j < OW_PER_THREAD; ++j) {
                acc[j][4 * c4 + 0] += xv[j] * wv.x;
                acc[j][4 * c4 + 1] += xv[j] * wv.y;
                acc[j][4 * c4 + 2] += xv[j] * wv.z;
                acc[j][4 * c4 + 3] += xv[j] * wv.w;
              }
            }
          } else if constexpr (CO_TILE % 2 == 0) {   // CO_TILE == 2
            float2 wv = *reinterpret_cast<const float2*>(wbase);
            #pragma unroll
            for (int j = 0; j < OW_PER_THREAD; ++j) {
              acc[j][0] += xv[j] * wv.x;
              acc[j][1] += xv[j] * wv.y;
            }
          } else {                                   // CO_TILE == 1
            const float wv = wbase[0];
            #pragma unroll
            for (int j = 0; j < OW_PER_THREAD; ++j) {
              acc[j][0] += xv[j] * wv;
            }
          }
        }  // kw
      }    // kh
    }      // ci
  }        // PH > 0 && PW > 0
  #pragma unroll
  for (int j = 0; j < OW_PER_THREAD; ++j) {
    if (live[j]) {
      #pragma unroll
      for (int co = 0; co < CO_TILE; ++co) {
        mY(n, co0 + co, oh, ow[j]) = acc[j][co];
      }
    }
  }
}
template <int CO_TILE>
static void launch_conv_transpose2d(
    const float* Xp, const float* Wp, const float* Bp, float* Yp,
    int N, int IC, int H, int W,
    int OC, int HO, int WO,
    int KH, int KW, int ICG, int OCG,
    int sh, int sw, int ph, int pw, int dh, int dw,
    cudaStream_t stream)
{
  constexpr int TH = 8;
  constexpr int TW = 16;
  constexpr int OW_PER_THREAD = 4;
  dim3 block(TH * TW);
  dim3 grid((unsigned)((WO + OW_PER_THREAD * TW - 1) / (OW_PER_THREAD * TW)),
            (unsigned)((HO + TH - 1) / TH),
            (unsigned)(N * (OC / CO_TILE)));
  int PHmax = (int)std::min<int64_t>(H, ((TH - 1) + (int64_t)(KH - 1) * dh) / sh + 2);
  int PWmax = (int)std::min<int64_t>(W, ((OW_PER_THREAD * TW - 1) + (int64_t)(KW - 1) * dw) / sw + 2);
  size_t smem_bytes =
      ((size_t)CO_TILE * ICG * KH * KW + (size_t)ICG * PHmax * PWmax) * sizeof(float)
      + ((size_t)TH * KH + (size_t)(OW_PER_THREAD * TW) * KW) * sizeof(int) + (size_t)CO_TILE * sizeof(float);
  if (smem_bytes > 48 * 1024) {
    auto err = cudaFuncSetAttribute(conv_transpose2d_cute_kernel<CO_TILE>,
                                    cudaFuncAttributeMaxDynamicSharedMemorySize,
                                    (int)smem_bytes);
    TORCH_CHECK(err == cudaSuccess, "cudaFuncSetAttribute failed: ",
                cudaGetErrorString(err));
  }
  conv_transpose2d_cute_kernel<CO_TILE><<<grid, block, smem_bytes, stream>>>(
      Xp, Wp, Bp, Yp,
      N, IC, H, W, OC, HO, WO,
      KH, KW, ICG, OCG,
      sh, sw, ph, pw, dh, dw,
      PHmax, PWmax);
}

torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                       torch::Tensor w,
                                       c10::optional<torch::Tensor> b,
                                       int64_t sh, int64_t sw,
                                       int64_t ph, int64_t pw,
                                       int64_t dh, int64_t dw,
                                       int64_t groups)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, IC, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [IC, OC/groups, KH, KW]");
  TORCH_CHECK(groups > 0 && sh > 0 && sw > 0 && dh > 0 && dw > 0,
              "groups/stride/dilation must be positive");
  TORCH_CHECK(ph >= 0 && pw >= 0, "padding must be non-negative");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int64_t N  = x_c.size(0);
  int64_t IC = x_c.size(1);
  int64_t H  = x_c.size(2);
  int64_t W  = x_c.size(3);

  int64_t KH  = w_c.size(2);
  int64_t KW  = w_c.size(3);
  int64_t OCG = w_c.size(1);

  TORCH_CHECK(w_c.size(0) == IC, "w.size(0) must equal in_channels");
  TORCH_CHECK(IC % groups == 0, "in_channels must be divisible by groups");

  int64_t ICG = IC / groups;
  int64_t OC  = OCG * groups;

  torch::Tensor b_c;
  const float* Bp = nullptr;
  if (b.has_value() && b->defined()) {
    TORCH_CHECK(b->is_cuda() && b->scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    b_c = b->contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    Bp = b_c.data_ptr<float>();
  }

  int64_t HO = (H - 1) * sh - 2 * ph + dh * (KH - 1) + 1;
  int64_t WO = (W - 1) * sw - 2 * pw + dw * (KW - 1) + 1;
  TORCH_CHECK(HO > 0 && WO > 0, "Invalid output size");

  auto y = torch::empty({N, OC, HO, WO}, x.options());

  int co_tile = (OCG % 8 == 0) ? 8 : ((OCG % 4 == 0) ? 4 : ((OCG % 2 == 0) ? 2 : 1));

  int64_t gridZ = N * (OC / co_tile);
  TORCH_CHECK(gridZ <= 65535, "gridDim.z limit exceeded");

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (co_tile == 8) {
    launch_conv_transpose2d<8>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), Bp,
                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  } else if (co_tile == 4) {
    launch_conv_transpose2d<4>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), Bp,
                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  } else if (co_tile == 2) {
    launch_conv_transpose2d<2>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), Bp,
                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  } else {
    launch_conv_transpose2d<1>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), Bp,
                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose2d kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
