                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  } else if (co_tile == 4) {
    launch_conv_transpose2d<4>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), Bp,
                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  } else if (co_tile == 2) {
    launch_conv_transpose2d<2>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), Bp,
                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  } else {
    launch_conv_transpose2d<1>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), Bp,
                               y.data_ptr<float>(),
                               (int)N, (int)IC, (int)H, (int)W,
                               (int)OC, (int)HO, (int)WO,
                               (int)KH, (int)KW, (int)ICG, (int)OCG,
                               (int)sh, (int)sw, (int)ph, (int)pw, (int)dh, (int)dw,
                               stream);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose2d kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
